-- Read models for the shared API client, plus final hardening.

-- The catalogue JSON documents are generated by scripts/generate-supabase-seed.mjs from
-- packages/catalog/src/data/*.json. They preserve the exact shared TypeScript shapes so
-- web and mobile consume identical data from either the dev API or Supabase.
CREATE TABLE IF NOT EXISTS public.catalog_documents (
  id          text PRIMARY KEY,
  document    jsonb NOT NULL,
  updated_at  timestamptz NOT NULL DEFAULT now()
);

CREATE OR REPLACE FUNCTION public.rpc_catalog()
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
  SELECT COALESCE((SELECT document FROM public.catalog_documents WHERE id = 'catalog'), '{}'::jsonb);
$$;
GRANT EXECUTE ON FUNCTION public.rpc_catalog() TO anon, authenticated;

CREATE OR REPLACE FUNCTION public.rpc_credits()
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
  SELECT jsonb_build_object(
    'policy', 'Only photographs whose subject and licence were verified are displayed. Unverified images and places without a licensed photograph show a designed unavailable state.',
    'credits', COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'place', i.place, 'alt', i.alt, 'credit', i.author, 'license', i.license, 'sourceUrl', i.source_url
      )) FROM public.image_sources i WHERE i.displayable), '[]'::jsonb),
    'unavailablePlaces', COALESCE((SELECT jsonb_agg(d.name) FROM public.destinations d
        WHERE NOT EXISTS (SELECT 1 FROM public.destination_images di
                          WHERE di.destination_id = d.id AND di.status = 'verified')), '[]'::jsonb)
  );
$$;
GRANT EXECUTE ON FUNCTION public.rpc_credits() TO anon, authenticated;

-- Unified account read: profile + roles in one round trip.
CREATE OR REPLACE FUNCTION public.rpc_me()
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE u uuid := public.gowayy_require_user(); p public.profiles%ROWTYPE; roles jsonb;
BEGIN
  SELECT * INTO p FROM public.profiles WHERE id = u AND deleted_at IS NULL;
  IF p.id IS NULL THEN RAISE EXCEPTION 'PROFILE_NOT_FOUND' USING ERRCODE = '42501'; END IF;
  SELECT COALESCE(jsonb_agg(role), '[]'::jsonb) INTO roles FROM public.user_roles WHERE user_id = u;
  RETURN jsonb_build_object('id', p.id, 'firstName', p.first_name, 'lastName', p.last_name,
    'roles', roles, 'createdAt', p.created_at, 'theme', p.theme, 'locale', p.locale);
END $$;
GRANT EXECUTE ON FUNCTION public.rpc_me() TO authenticated;

-- Hardening: every table created after the RLS migration is protected too.
DO $$
DECLARE t record;
BEGIN
  FOR t IN SELECT tablename FROM pg_tables WHERE schemaname = 'public' LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t.tablename);
  END LOOP;
END $$;

DROP POLICY IF EXISTS catalog_documents_public_read ON public.catalog_documents;
CREATE POLICY catalog_documents_public_read ON public.catalog_documents FOR SELECT TO anon, authenticated USING (true);
GRANT SELECT ON public.catalog_documents TO anon, authenticated;

-- service_role exists on Supabase (not in the local verification harness). Only these
-- two server-only functions are granted to it; clients never receive the service key.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN
    EXECUTE 'GRANT EXECUTE ON FUNCTION public.rpc_webhook_capture(text, jsonb) TO service_role';
    EXECUTE 'GRANT EXECUTE ON FUNCTION public.rpc_finalize_registration(uuid) TO service_role';
  END IF;
END $$;

-- PostGIS attach again in case the earlier pass ran before a spatial table was added.
SELECT public.gowayy_attach_geo();
